use alloy_primitives::{U256, address, Bytes};
use revm::{
    db::BenchmarkDB,
    primitives::{Bytecode, TransactTo},
    Evm,
};
use serde_json::json;
use std::fs::File;
use std::io::Write;

fn main() {
    let bytecode_hex = "";
    let bytecode = Bytecode::new_raw(Bytes::from(hex::decode(bytecode_hex).unwrap()));

    let mut db = BenchmarkDB::new_bytecode(bytecode.clone());
    let irm_address = address!("1234567890123456789012345678901234567890");

    let seeds = vec![
        (U256::from(1000e18 as u128), U256::from(800e18 as u128), 3600),
        (U256::from(1000e18 as u128), U256::from(999e18 as u128), 60),
        (U256::from(1e6 as u128), U256::from(1 as u128), 31536000),
    ];

    let mut results = Vec::new();

    for (supply, borrow, elapsed) in seeds {
        let mut evm = Evm::builder()
            .with_db(&mut db)
            .modify_tx_env(|tx| {
                tx.caller = address!("0000000000000000000000000000000000000001");
                tx.transact_to = TransactTo::Call(irm_address);
                tx.data = Bytes::from(hex::decode("00000000").unwrap());
                tx.chain_id = Some(1);
            })
            .build();

        let result = evm.transact().unwrap();
        results.push(json!({
            "supply": supply.to_string(),
            "borrow": borrow.to_string(),
            "elapsed": elapsed,
            "gas_used": result.result.gas_used(),
            "output": result.result.output().map(|o| hex::encode(o)).unwrap_or_default(),
        }));
    }

    let json_output = json!(results).to_string();
    let mut file = File::create("irm_divergence_report.json").unwrap();
    file.write_all(json_output.as_bytes()).unwrap();
    println!("IRM divergence report generated.");
}
